class PriceEngine:
    DISCOUNT_PRO = 0.90

    @staticmethod
    def price(plan, amount):
        """
        Calculate the price based on the plan and apply discount if necessary.

        Args:
        plan (str): The plan type ('basic' or 'pro' or any other plan with a set discount).
        amount (float): The original amount before applying any discounts.

        Returns:
        float: The final price after applying the discount, rounded to 2 decimal places.

        Raises:
        KeyError: If the plan is not recognized.
        """
        if plan == 'basic':
            return round(amount, 2)
        elif plan in {'pro'}:
            discounted_amount = amount * PriceEngine.DISCOUNT_PRO
            return round(discounted_amount, 2)
        else:
            try:
                discount = PriceEngine.get_discount(plan)
                discounted_amount = amount * discount
                return round(discounted_amount, 2)
            except KeyError:
                raise KeyError(f"Unknown plan: {plan}")

    @staticmethod
    def set_discount(plan, fraction):
        """
        Set the discount for a given plan at runtime.

        Args:
        plan (str): The plan type.
        fraction (float): The discount fraction (e.g., 0.85 for 15% off).

        Raises:
        ValueError: If the fraction is not between 0 and 1.
        """
        if not (0 <= fraction <= 1):
            raise ValueError("Discount fraction must be between 0 and 1.")
        setattr(PriceEngine, f'DISCOUNT_{plan.upper()}', fraction)

    @staticmethod
    def get_discount(plan):
        """
        Get the discount for a given plan.

        Args:
        plan (str): The plan type.

        Returns:
        float: The discount fraction.

        Raises:
        KeyError: If the plan is not recognized.
        """
        try:
            return getattr(PriceEngine, f'DISCOUNT_{plan.upper()}')
        except AttributeError:
            raise KeyError(f"Unknown plan: {plan}")
