class Permissions:
    def __init__(self):
        self._roles = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }
        self._inherited_roles = {}

    def define_role(self, name, actions, inherits=None):
        """
        Define a new role with specified actions and optionally inherit from another role.

        :param name: str, the name of the role to define
        :param actions: dict, the actions allowed for this role
        :param inherits: str, the name of the role to inherit from (optional)
        """
        if inherits:
            base_actions = self._roles.get(inherits, {})
            actions = {**base_actions, **actions}
        self._roles[name] = actions
        if inherits:
            self._inherited_roles.setdefault(name, []).append(inherits)

    def allowed(self, role, action):
        """
        Check if the given role is allowed to perform the specified action.

        :param role: str, the role to check (e.g., 'viewer', 'editor')
        :param action: str, the action to check (e.g., 'read', 'write')
        :return: bool, True if the role is allowed to perform the action, otherwise False
        """
        if role not in self._roles:
            return False
        role_actions = self._roles[role]
        if action in role_actions and role_actions[action]:
            return True
        for inherited_role in self._inherited_roles.get(role, []):
            if self.allowed(inherited_role, action):
                return True
        return False


# Example usage:
perm = Permissions()
perm.define_role('viewer', {'read': True})
perm.define_role('editor', {'read': True, 'write': True})
perm.define_role('moderator', {'write': True}, 'editor')
print(perm.allowed('viewer', 'read'))  # Output: True
print(perm.allowed('editor', 'write'))  # Output: True
print(perm.allowed('moderator', 'read'))  # Output: True
print(perm.allowed('moderator', 'write'))  # Output: True
print(perm.allowed('moderator', 'delete'))  # Output: False
