from typing import Set

class Permissions:
    def __init__(self):
        self._permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        """
        Check if the given role is allowed to perform the specified action.

        :param role: str, the role to check (e.g., 'viewer', 'editor')
        :param action: str, the action to check (e.g., 'read', 'write')
        :return: bool, True if the role is allowed to perform the action, otherwise False
        """
        if role not in self._permissions:
            return False
        return action in self._permissions[role]

    def effective(self, role) -> Set[str]:
        """
        Return a set of actions that the given role is allowed to perform.

        :param role: str, the role to check (e.g., 'viewer', 'editor')
        :return: set of str, actions the role is allowed to perform
        """
        if role not in self._permissions:
            return set()
        return set(self._permissions[role].keys())

    def restrict(self, role, allowed_actions: Set[str]) -> Set[str]:
        """
        Intersect the current permissions for the given role with the supplied set of allowed actions.

        :param role: str, the role to check (e.g., 'viewer', 'editor')
        :param allowed_actions: set of str, the actions to allow
        :return: set of str, the intersection of current permissions and allowed actions
        """
        if role not in self._permissions:
            return set()
        current_permissions = set(self._permissions[role].keys())
        return current_permissions.intersection(allowed_actions)


# Example usage:
# perm = Permissions()
# print(perm.effective('viewer'))  # Output: {'read'}
# print(perm.effective('editor'))  # Output: {'read', 'write'}
# print(perm.restrict('editor', {'read', 'write', 'delete'}))  # Output: {'read', 'write'}
```

