            'viewer': {'read': True, 'write': False},
            'editor': {'read': True, 'write': True}
        }

    def define_role(self, name, actions, inherits=None):
        if inherits is None:
            inherits = []
        elif isinstance(inherits, str):
            inherits = [inherits]
        else:
            inherits = list(inherits)

        base_permissions = {action: False for action in actions}
        for inherit in inherits:
            base_permissions.update(self.roles.get(inherit, {}))

        self.roles[name] = base_permissions

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        permissions = self.roles[role]
        return permissions.get(action, False)

