from typing import Set

class Permissions:
    def __init__(self):
        self.roles = {
            'viewer': {'read': True, 'write': False},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        permissions = self.roles[role]
        return permissions.get(action, False)

    def effective(self, role) -> Set[str]:
        if role not in self.roles:
            return set()
        return set(self.roles[role].keys())

    def restrict(self, role, allowed_actions: Set[str]) -> Set[str]:
        if role not in self.roles:
            return set()
        current_permissions = self.roles[role]
        return {action for action in current_permissions.keys() if current_permissions[action] and action in allowed_actions}

# Example usage:
permissions = Permissions()
print(permissions.effective('viewer'))  # Output: {'read', 'write'}
print(permissions.restrict('viewer', {'read'}))  # Output: {'read'}

print(permissions.allowed('viewer', 'read'))  # Output: True
print(permissions.allowed('viewer', 'write'))  # Output: False
print(permissions.allowed('editor', 'read'))  # Output: True
print(permissions.allowed('editor', 'write'))  # Output: True
print(permissions.allowed('admin', 'read'))   # Output: False
