class Permissions:
    READ = 'read'
    WRITE = 'write'

    def __init__(self):
        self.roles = {
            'viewer': {self.READ},
            'editor': {self.READ, self.WRITE}
        }
        self.inheritance = {}

    def define_role(self, name, actions, inherits=None):
        if inherits is not None:
            if isinstance(inherits, str):
                inherits = [inherits]
            for role in inherits:
                if role not in self.roles:
                    raise ValueError(f"Role {role} does not exist")
                self.inheritance[name] = inherits
                self.roles[name] = self.resolve_inheritance(name)
        else:
            self.roles[name] = set(actions)

    def resolve_inheritance(self, role):
        inherited_permissions = set()
        queue = [role]
        while queue:
            current_role = queue.pop(0)
            if current_role in self.inheritance:
                for parent_role in self.inheritance[current_role]:
                    if parent_role not in queue and parent_role != current_role:
                        queue.append(parent_role)
            inherited_permissions.update(self.roles.get(current_role, set()))
        return inherited_permissions

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        return action in self.resolve_inheritance(role)
