class Permissions:
    def __init__(self):
        self.roles = {
            'viewer': {'actions': {'read'}},
            'editor': {'actions': {'read', 'write'}}
        }

    def define_role(self, name, actions, inherits=None):
        if inherits is None:
            inherits = set()
        else:
            inherits = self.resolve_inheritance(inherits)

        self.roles[name] = {'actions': actions, 'inherits': inherits}

    def resolve_inheritance(self, roles):
        result = set()
        for role in roles:
            result.update(self.roles[role]['actions'])
            result.update(self.resolve_inheritance(self.roles[role]['inherits']))
        return result

    def allowed(self, role, action):
        return action in self.resolve_inheritance([role])

# Example usage:
permissions = Permissions()
permissions.define_role('admin', {'read', 'write', 'delete'})
permissions.define_role('moderator', {'read', 'write'}, ['admin'])
permissions.define_role('guest', {'read'}, ['viewer'])

print(permissions.allowed('viewer', 'read'))  # True
print(permissions.allowed('editor', 'write'))  # True
print(permissions.allowed('moderator', 'delete'))  # True
print(permissions.allowed('guest', 'write'))  # False
```

