class Permissions:
    def __init__(self):
        self.roles = {
            'viewer': {'actions': ['read']},
            'editor': {'actions': ['read', 'write']}
        }
        self.inheritance = {}

    def define_role(self, name, actions, inherits=None):
        if inherits is None:
            self.roles[name] = {'actions': list(actions)}
        else:
            base_actions = set(self.roles[inherits]['actions'])
            base_actions.update(actions)
            self.roles[name] = {'actions': list(base_actions)}
            self.inheritance[name] = inherits

    def allowed(self, role, action):
        if role in self.roles:
            if role in self.inheritance:
                for r in self._resolve_inheritance(role):
                    if action in self.roles[r]['actions']:
                        return True
            else:
                return action in self.roles[role]['actions']
        return False

    def _resolve_inheritance(self, role):
        if role not in self.inheritance:
            return [role]
        else:
            return [role] + self._resolve_inheritance(self.inheritance[role])
