            self.roles[name] = set(actions)

    def allowed(self, role, action):
        return action in self._get_permissions(role)

    def _get_permissions(self, role):
        if role not in self.roles:
            return set()
        permissions = self.roles[role].copy()
        for parent_role in self._get_inherited_roles(role):
            permissions.update(self._get_permissions(parent_role))
        return permissions

    def _get_inherited_roles(self, role):
        if role not in self.roles:
            return []
        inherited_roles = self.roles.get(role, {}).get("inherits", [])
        return [r for r in inherited_roles if r in self.roles] + sum(
            [self._get_inherited_roles(r) for r in inherited_roles], []
        )
```

