from typing import Set

class Permissions:
    def allowed(self, role: str, action: str) -> bool:
        if role == "viewer":
            return action in {"read"}
        elif role == "editor":
            return action in {"read", "write"}
        else:
            return False

    def effective(self, role: str) -> Set[str]:
        if role == "viewer":
            return {"read"}
        elif role == "editor":
            return {"read", "write"}
        else:
            return set()

    def restrict(self, role: str, allowed_actions: Set[str]) -> Set[str]:
        effective_actions = self.effective(role)
        return effective_actions.intersection(allowed_actions)
