from collections import defaultdict

class Permissions:
    def __init__(self):
        self.roles = defaultdict(dict)

    def define_role(self, name, actions, inherits=None):
        if inherits:
            for action in self.roles[inherits]:
                if action not in actions:
                    actions[action] = True
