        self.pricing_strategy = {
            'basic': lambda amount: round(amount, 2),
            'pro': lambda amount: round(amount * 0.9, 2)
        }
        self.promotion_strategy = {
            'half_off': lambda amount, fraction: round(amount * (1 - fraction), 2),
            'quarter_off': lambda amount, fraction: round(amount * (1 - fraction / 4), 2)
        }

    def price(self, plan, amount):
        if plan not in self.pricing_strategy:
            raise KeyError(f"Unknown plan: {plan}")
        return self.pricing_strategy[plan](amount)

    def price_with_promotions(self, plan, amount, promotions):
        base_price = self.price(plan, amount)
        for promotion in promotions:
            if promotion not in self.promotion_strategy:
                raise KeyError(f"Unknown promotion: {promotion}")
            base_price = self.promotion_strategy[promotion](base_price, 1)
        return base_price

