class PriceEngine:
    def __init__(self):
        self.plans = {
            'basic': 0.0,  # Basic plan has no discount
            'pro': 0.10  # Pro plan has a 10% discount
        }

    def price(self, plan, amount):
        # Check if the plan is valid
        if plan not in self.plans:
            raise KeyError(f"Unknown plan '{plan}'. Available plans are: {', '.join(self.plans.keys())}")

        # Calculate price based on the plan
        price = amount * (1 - self.plans[plan])

        # Round the price to 2 decimal places
        return round(price, 2)

    def set_discount(self, plan, fraction):
        # Set the discount for the given plan
        if plan in self.plans:
            self.plans[plan] = fraction
        else:
            raise KeyError(f"Plan '{plan}' does not exist. Please create it first using add_plan().")

    def add_plan(self, plan):
        # Add a new plan with default 0% discount
        if plan not in self.plans:
            self.plans[plan] = 0.0
        else:
            raise KeyError(f"Plan '{plan}' already exists.")

