class FeatureFlags:
    def __init__(self):
        self.flags = {}
        self.checkpoints = []

    def set(self, name, enabled):
        if not isinstance(name, str) or not isinstance(enabled, bool):
            raise ValueError("Name must be a string and enabled must be a boolean.")
        self.checkpoints.append({'flags': self.flags.copy(), 'name': name, 'enabled': enabled})
        self.flags[name] = enabled

    def get(self, name):
        return self.flags.get(name, False)

    def export(self):
        return self.flags

    def checkpoint(self):
        self.checkpoints.append({'flags': self.flags.copy()})

    def rollback(self, checkpoint):
        for i, cp in enumerate(self.checkpoints):
            if cp['flags'] == checkpoint['flags']:
                del self.checkpoints[i:]
                self.flags = cp['flags']
                break

