class Permissions:
    def __init__(self):
        self.roles_permissions = {
            'viewer': ['read'],
            'editor': ['read', 'write']
        }
        self.role_hierarchy = {
            'editor': 'viewer'
        }

    def define_role(self, name, actions, inherits=None):
        if inherits:
            if inherits not in self.roles_permissions:
                raise ValueError(f"Inherited role '{inherits}' does not exist.")
            self.roles_permissions[name] = self.roles_permissions[inherits] + actions
        else:
            self.roles_permissions[name] = actions

    def allowed(self, role, action):
        if role not in self.roles_permissions:
            return False  # Unknown roles are denied
        role_stack = [role]
        while role_stack:
            current_role = role_stack.pop()
            if action in self.roles_permissions[current_role]:
                return True
            if current_role in self.role_hierarchy:
                role_stack.append(self.role_hierarchy[current_role])
        return False

