from typing import Set

class Permissions:
    def __init__(self):
        self.roles_permissions = {
            'viewer': {'read'},
            'editor': {'read', 'write'}
        }

    def allowed(self, role, action):
        if role not in self.roles_permissions:
            return False
        return action in self.roles_permissions[role]

    def effective(self, role) -> Set[str]:
        return self.roles_permissions.get(role, set())

    def restrict(self, role, allowed_actions: Set[str]) -> Set[str]:
        if role not in self.roles_permissions:
            return set()
        current_permissions = self.roles_permissions[role]
        restricted_permissions = current_permissions.intersection(allowed_actions)
        self.roles_permissions[role] = restricted_permissions
        return restricted_permissions

