class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }
        self.inheritance = {}

    def define_role(self, name, actions, inherits=None):
        if inherits:
            parent_permissions = self.permissions.get(inherits, {})
            self.permissions[name] = {**parent_permissions, **actions}
            self.inheritance[name] = inherits
        else:
            self.permissions[name] = actions
            self.inheritance[name] = None

    def allowed(self, role, action):
        # Check if the role exists in the permissions dictionary
        if role in self.permissions:
            # Check if the action is allowed for the role
            return self.permissions[role].get(action, False)
        else:
            # If the role is not recognized, deny the action
            return False

    def resolve_inheritance(self, role):
        while role in self.inheritance and self.inheritance[role]:
            role = self.inheritance[role]
            if role in self.permissions:
                return role
        return role

    def allowed_with_inheritance(self, role, action):
        resolved_role = self.resolve_inheritance(role)
        return self.allowed(resolved_role, action)

