        self.flags = {
            'search': False,
            'export': False
        }

    def set(self, name, enabled):
        if name in self.flags:
            self.flags[name] = enabled
        else:
            raise KeyError(f"Unknown feature flag: {name}")

    def get(self, name):
        return self.flags.get(name, False)

    def set_many(self, mapping):
        for name, enabled in mapping.items():
            if name not in self.flags:
                raise KeyError(f"Unknown feature flag: {name}")
            if not isinstance(enabled, bool):
                raise ValueError(f"Value for feature flag '{name}' must be a boolean")
        self.flags.update({name: enabled for name, enabled in mapping.items()})
```

