class FeatureFlags:
    def __init__(self):
        self.flags = {
            'search': False,
            'export': False
        }
        self.checkpoints = []

    def set(self, name, enabled):
        if name in self.flags:
            self.flags[name] = enabled
            self.checkpoint()
        else:
            raise KeyError(f"Unknown feature flag: {name}")

    def get(self, name):
        return self.flags.get(name, False)

    def checkpoint(self):
        self.checkpoints.append(dict(self.flags))

    def rollback(self, cp):
        self.flags = dict(cp)
