class Permissions:
    def __init__(self):
        self.roles = {}
        self.inheritance_tree = {}

    def define_role(self, name, actions, inherits=None):
        if inherits is None:
            inherits = []
        elif isinstance(inherits, str):
            inherits = [inherits]
        elif not isinstance(inherits, list):
            raise ValueError("Inherits must be a string or a list of strings")

        inherited_actions = set()
        for role in inherits:
            if role not in self.roles:
                raise ValueError(f"Role {role} does not exist")
            inherited_actions.update(self.roles[role])

        self.roles[name] = set(actions).union(inherited_actions)
        for role in inherits:
            self._add_inheritance(name, role)

    def _add_inheritance(self, child, parent):
        if child not in self.inheritance_tree:
            self.inheritance_tree[child] = set()
        self.inheritance_tree[child].add(parent)

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        return action in self.roles[role]

# Example usage:
permissions = Permissions()
permissions.define_role('viewer', ['read'])
permissions.define_role('editor', ['read', 'write'], 'viewer')
permissions.define_role('admin', ['read', 'write', 'delete'], ['editor'])

print(permissions.allowed('viewer', 'read'))  # True
print(permissions.allowed('editor', 'write'))  # True
print(permissions.allowed('admin', 'delete'))  # True
print(permissions.allowed('unknown', 'read'))  # False
```

