class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': {'read'},
            'editor': {'read', 'write'}
        }

    def allowed(self, role, action: str) -> bool:
        if role not in self.permissions:
            return False
        return action in self.permissions[role]

    def effective(self, role) -> Set[str]:
        return self.permissions.get(role, set())

    def restrict(self, role, allowed_actions: Set[str]) -> Set[str]:
        if role not in self.permissions:
            return set()
        current_permissions = self.permissions[role]
        return current_permissions.intersection(allowed_actions)

