class Permissions:
    def __init__(self):
        self.roles = {
            'viewer': {'actions': ['read'], 'inherits': None},
            'editor': {'actions': ['read', 'write'], 'inherits': 'viewer'}
        }

    def define_role(self, name, actions, inherits=None):
        if inherits is not None and inherits in self.roles:
            self.roles[name] = {'actions': list(set(actions + self.roles[inherits]['actions'])), 'inherits': inherits}
        else:
            self.roles[name] = {'actions': actions, 'inherits': inherits}

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        current_role = role
        while current_role:
            if action in self.roles[current_role]['actions']:
                return True
            current_role = self.roles[current_role]['inherits']
        return False

