from collections import defaultdict

class EventStore:
    def __init__(self):
        self._events = defaultdict(list)

    def record(self, user, value):
        self._events[user].append(value)

    def latest(self, user):
        events = self._events.get(user, [])
        if events:
            return events[-1]
        return None

    def history(self, user):
        return self._events.get(user, [])
