class EventStore:
    def __init__(self):
        self._events = {}
        self._history = {}

    def record(self, user, value):
        self._history[user] = self._events.get(user, None)
        self._events[user] = value

    def latest(self, user):
        return self._events.get(user, None)

    def undo(self, user):
        previous_value = self._events[user] if user in self._events else None
        self._events[user] = self._history.pop(user, None)
        return previous_value
