    def __init__(self):
        self._store = {}
        self._history = {}

    def record(self, user, value):
        self._store[user] = value
        self._history[user] = (value, self._store.get(user, None))

    def latest(self, user):
        return self._store.get(user, None)

    def undo(self, user):
        if user in self._history:
            value, prev_value = self._history.pop(user)
            self._store[user] = prev_value
            return value
        return None
