class EventStore:
    def __init__(self):
        self._store = {}
        self._history = {}

    def record(self, user, value):
        self._store[user] = value
        if user in self._history:
            self._history[user].append(value)
        else:
            self._history[user] = [value]

    def latest(self, user):
        return self._store.get(user, None)

    def undo(self, user):
        if user in self._store:
            value = self._store[user]
            if len(self._history[user]) > 1:
                self._store[user] = self._history[user].pop()
            else:
                del self._history[user]
                del self._store[user]
            return value
        return None
```

